"use strict";

// Draws all charts of the page from window.RADON_DATA (generated by scripts/build_site_data.py).
// No chart library: every chart is plain SVG, so each line can be explained.

const SVG_NS = "http://www.w3.org/2000/svg";
const MARGIN = { top: 28, right: 16, bottom: 28, left: 40 };
const TARGET_TICK_COUNT = 4;
const DOT_RADIUS = 4;
const COLUMN_GAP = 2;
const COLUMN_CORNER = 4;
const TOOLTIP_OFFSET = 16;
const NARROW_CHART_WIDTH = 560;
const MS_PER_HOUR = 3600 * 1000;

const numberFormat = new Intl.NumberFormat("de-AT");
const decimalFormat = new Intl.NumberFormat("de-AT", { maximumFractionDigits: 1 });
const dayFormat = new Intl.DateTimeFormat("de-AT", { day: "2-digit", month: "2-digit" });
const longDayFormat = new Intl.DateTimeFormat("de-AT", { weekday: "short", day: "2-digit", month: "2-digit" });
const monthFormat = new Intl.DateTimeFormat("de-AT", { month: "short" });

const tooltip = document.getElementById("tooltip");

// ------------------------------------------------------------------ small helpers

function createSvgElement(name, attributes) {
  const element = document.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attributes)) {
    element.setAttribute(key, value);
  }
  return element;
}

function createHtmlElement(name, className, text) {
  const element = document.createElement(name);
  if (className) element.className = className;
  if (text !== undefined) element.textContent = text;
  return element;
}

// "2026-03-24" must become local midnight; new Date("2026-03-24") would be UTC midnight.
function parseDay(isoDay) {
  const [year, month, day] = isoDay.split("-").map(Number);
  return new Date(year, month - 1, day).getTime();
}

function formatHour(time) {
  const date = new Date(time);
  return `${longDayFormat.format(date)} ${date.getHours()} Uhr`;
}

// Round the axis maximum up to a clean number (steps of 1, 2 or 5 times a power of ten).
function chooseAxisStep(maxValue) {
  const roughStep = maxValue / TARGET_TICK_COUNT;
  const magnitude = 10 ** Math.floor(Math.log10(roughStep));
  const candidates = [1, 2, 5, 10].map((factor) => factor * magnitude);
  return candidates.find((step) => step >= roughStep);
}

// ------------------------------------------------------------------ tooltip

function showTooltip(title, rows, clientX, clientY) {
  tooltip.replaceChildren(createHtmlElement("div", "tooltip-title", title));
  for (const row of rows) {
    const rowElement = createHtmlElement("div", "tooltip-row");
    // Only the key wears the series color; text stays in text colors so it is always readable.
    if (row.colorClass) rowElement.append(createHtmlElement("span", `legend-key ${row.colorClass}`));
    rowElement.append(createHtmlElement("span", "tooltip-value", row.value));
    rowElement.append(createHtmlElement("span", "tooltip-label", row.label));
    tooltip.append(rowElement);
  }
  tooltip.hidden = false;
  // Flip to the left of the pointer when the tooltip would leave the window.
  const fitsRight = clientX + TOOLTIP_OFFSET + tooltip.offsetWidth < window.innerWidth;
  const left = fitsRight ? clientX + TOOLTIP_OFFSET : clientX - TOOLTIP_OFFSET - tooltip.offsetWidth;
  tooltip.style.left = `${Math.max(left, 0)}px`;
  tooltip.style.top = `${Math.max(clientY - tooltip.offsetHeight - TOOLTIP_OFFSET, 0)}px`;
}

function hideTooltip() {
  tooltip.hidden = true;
}

// ------------------------------------------------------------------ chart frame

// Creates the empty SVG with y-axis, grid and x-axis labels. Returns the scales for the marks.
function createFrame(container, options) {
  const width = container.clientWidth;
  const height = container.clientHeight;
  const left = MARGIN.left;
  const right = width - MARGIN.right;
  const top = MARGIN.top;
  const bottom = height - MARGIN.bottom;

  const step = chooseAxisStep(options.maxValue);
  const axisMax = Math.ceil(options.maxValue / step) * step;
  const [xMin, xMax] = options.xDomain;
  const xOf = (x) => left + ((x - xMin) / (xMax - xMin)) * (right - left);
  const yOf = (value) => bottom - (value / axisMax) * (bottom - top);

  const svg = createSvgElement("svg", { role: "img", tabindex: "0", "aria-label": options.ariaLabel });
  for (let value = 0; value <= axisMax; value += step) {
    svg.append(createSvgElement("line", { class: "grid-line", x1: left, x2: right, y1: yOf(value), y2: yOf(value) }));
    const label = createSvgElement("text", { class: "axis-text", x: left - 8, y: yOf(value) + 4, "text-anchor": "end" });
    label.textContent = numberFormat.format(value);
    svg.append(label);
  }
  for (const tick of options.xTicks) {
    const label = createSvgElement("text", { class: "axis-text", x: xOf(tick.x), y: bottom + 20, "text-anchor": "middle" });
    label.textContent = tick.label;
    svg.append(label);
  }
  container.replaceChildren(svg);
  return { svg, width, left, right, top, bottom, xOf, yOf };
}

// Labels sit above the plot area so they can never cover data.
function drawAnnotations(frame, annotations) {
  for (const band of annotations.bands || []) {
    const x = frame.xOf(band.from);
    frame.svg.append(createSvgElement("rect", {
      class: "band", x, y: frame.top, width: frame.xOf(band.to) - x, height: frame.bottom - frame.top,
    }));
    drawAnnotationLabel(frame, x, band.label);
  }
  for (const marker of annotations.markers || []) {
    const x = frame.xOf(marker.x);
    frame.svg.append(createSvgElement("line", { class: "reference-line", x1: x, x2: x, y1: frame.top, y2: frame.bottom }));
    drawAnnotationLabel(frame, x, marker.label);
  }
  for (const reference of annotations.referenceLines || []) {
    const y = frame.yOf(reference.value);
    frame.svg.append(createSvgElement("line", { class: "reference-line", x1: frame.left, x2: frame.right, y1: y, y2: y }));
    const label = createSvgElement("text", { class: "annotation-text", x: frame.right, y: y - 6, "text-anchor": "end" });
    label.textContent = reference.label;
    frame.svg.append(label);
  }
}

function drawAnnotationLabel(frame, x, text) {
  const label = createSvgElement("text", { class: "annotation-text", x, y: frame.top - 10 });
  label.textContent = text;
  frame.svg.append(label);
}

// Pointer and keyboard select the nearest data position; the chart decides what to show for it.
function attachSelection(frame, positions, onSelect, onClear) {
  const hitArea = createSvgElement("rect", {
    class: "hit-area", x: frame.left, y: frame.top, width: frame.right - frame.left, height: frame.bottom - frame.top,
  });
  frame.svg.append(hitArea);
  let activeIndex = -1;

  function select(index, clientX, clientY) {
    activeIndex = index;
    onSelect(index, clientX, clientY);
  }
  function clear() {
    activeIndex = -1;
    onClear();
    hideTooltip();
  }
  function findNearestIndex(pixelX) {
    let nearest = 0;
    for (let index = 1; index < positions.length; index += 1) {
      if (Math.abs(positions[index] - pixelX) < Math.abs(positions[nearest] - pixelX)) nearest = index;
    }
    return nearest;
  }

  hitArea.addEventListener("pointermove", (event) => {
    const bounds = frame.svg.getBoundingClientRect();
    select(findNearestIndex(event.clientX - bounds.left), event.clientX, event.clientY);
  });
  hitArea.addEventListener("pointerleave", clear);
  frame.svg.addEventListener("blur", clear);
  frame.svg.addEventListener("keydown", (event) => {
    if (event.key === "Escape") return clear();
    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
    event.preventDefault();
    const direction = event.key === "ArrowRight" ? 1 : -1;
    const start = activeIndex === -1 ? 0 : activeIndex + direction;
    const index = Math.min(Math.max(start, 0), positions.length - 1);
    const bounds = frame.svg.getBoundingClientRect();
    select(index, bounds.left + positions[index], bounds.top + frame.top);
  });
}

// ------------------------------------------------------------------ line chart

function buildLinePath(frame, xs, values) {
  let path = "";
  let isPenDown = false;
  values.forEach((value, index) => {
    // A missing value ends the line; the next value starts a new piece.
    if (value === null) {
      isPenDown = false;
      return;
    }
    path += `${isPenDown ? "L" : "M"}${frame.xOf(xs[index]).toFixed(1)},${frame.yOf(value).toFixed(1)}`;
    isPenDown = true;
  });
  return path;
}

function drawLineChart(config) {
  const allValues = config.series.flatMap((series) => series.values).filter((value) => value !== null);
  const referenceValues = (config.referenceLines || []).map((reference) => reference.value);
  const frame = createFrame(config.container, {
    maxValue: Math.max(...allValues, ...referenceValues),
    xDomain: [config.xs[0], config.xs[config.xs.length - 1]],
    xTicks: config.xTicks(config.container.clientWidth),
    ariaLabel: config.ariaLabel,
  });
  drawAnnotations(frame, config);

  for (const series of config.series) {
    frame.svg.append(createSvgElement("path", {
      class: `series-line ${series.colorClass}`, d: buildLinePath(frame, config.xs, series.values),
    }));
  }

  const crosshair = createSvgElement("line", { class: "crosshair", y1: frame.top, y2: frame.bottom, visibility: "hidden" });
  frame.svg.append(crosshair);
  const dots = config.series.map((series) => {
    const dot = createSvgElement("circle", { class: `series-dot ${series.colorClass}`, r: DOT_RADIUS, visibility: "hidden" });
    frame.svg.append(dot);
    return dot;
  });

  function showPosition(index, clientX, clientY) {
    const x = frame.xOf(config.xs[index]);
    crosshair.setAttribute("x1", x);
    crosshair.setAttribute("x2", x);
    crosshair.setAttribute("visibility", "visible");
    const rows = [];
    config.series.forEach((series, seriesIndex) => {
      const value = series.values[index];
      dots[seriesIndex].setAttribute("visibility", value === null ? "hidden" : "visible");
      if (value === null) return;
      dots[seriesIndex].setAttribute("cx", x);
      dots[seriesIndex].setAttribute("cy", frame.yOf(value));
      rows.push({ value: `${decimalFormat.format(value)} ${config.unit}`, label: series.label, colorClass: series.colorClass });
    });
    showTooltip(config.formatX(config.xs[index]), rows, clientX, clientY);
  }
  function hidePosition() {
    crosshair.setAttribute("visibility", "hidden");
    dots.forEach((dot) => dot.setAttribute("visibility", "hidden"));
  }
  attachSelection(frame, config.xs.map(frame.xOf), showPosition, hidePosition);
}

// ------------------------------------------------------------------ column chart

// Rounded corners only at the top: the bottom edge stands on the baseline.
function buildColumnPath(x, y, width, height) {
  const radius = Math.min(COLUMN_CORNER, width / 2, height);
  return `M${x},${y + height}V${y + radius}Q${x},${y} ${x + radius},${y}H${x + width - radius}`
    + `Q${x + width},${y} ${x + width},${y + radius}V${y + height}Z`;
}

function drawColumnChart(config) {
  const count = config.values.length;
  const frame = createFrame(config.container, {
    maxValue: Math.max(...config.values.filter((value) => value !== null)),
    // Half a slot of padding on both sides so the first and last column fit inside the plot.
    xDomain: [-0.5, count - 0.5],
    xTicks: config.xTicks(config.container.clientWidth),
    ariaLabel: config.ariaLabel,
  });
  drawAnnotations(frame, config);

  const slotWidth = frame.xOf(1) - frame.xOf(0);
  const columnWidth = Math.max(slotWidth - COLUMN_GAP, 1);
  const columns = config.values.map((value, index) => {
    if (value === null) return null;
    const y = frame.yOf(value);
    const column = createSvgElement("path", {
      class: `column ${config.colorClassOf(index)}`,
      d: buildColumnPath(frame.xOf(index) - columnWidth / 2, y, columnWidth, frame.bottom - y),
    });
    frame.svg.append(column);
    return column;
  });

  function clearActive() {
    columns.forEach((column) => column && column.classList.remove("is-active"));
  }
  function showColumn(index, clientX, clientY) {
    clearActive();
    if (columns[index] === null) return hideTooltip();
    columns[index].classList.add("is-active");
    const row = { value: `${decimalFormat.format(config.values[index])} ${config.unit}`, label: config.label };
    showTooltip(config.formatX(index), [row], clientX, clientY);
  }
  attachSelection(frame, config.values.map((_, index) => frame.xOf(index)), showColumn, clearActive);
}

// ------------------------------------------------------------------ legends and tiles

// With options.onToggle the entries become buttons that show or hide their series.
function drawLegend(containerId, items, options = {}) {
  const container = document.getElementById(containerId);
  const isToggle = options.onToggle !== undefined;
  const keyShape = options.isBox ? "legend-key is-box" : "legend-key";
  container.replaceChildren();
  for (const item of items) {
    const element = createHtmlElement(isToggle ? "button" : "span", "legend-item");
    // Only the key wears the series color; text stays in text colors so it is always readable.
    element.append(createHtmlElement("span", `${keyShape} ${item.colorClass}`));
    element.append(createHtmlElement("span", "legend-label", item.label));
    if (isToggle) {
      element.type = "button";
      element.setAttribute("aria-pressed", "true");
      element.addEventListener("click", () => {
        const isVisible = options.onToggle(item.key);
        element.setAttribute("aria-pressed", String(isVisible));
      });
    }
    container.append(element);
  }
}

function drawTiles(containerId, tiles) {
  const container = document.getElementById(containerId);
  container.replaceChildren();
  for (const tile of tiles) {
    const element = createHtmlElement("div", "tile");
    element.append(createHtmlElement("dt", "", tile.label));
    const value = createHtmlElement("dd", "tile-value", tile.value);
    value.append(" ", createHtmlElement("span", "tile-unit", tile.unit));
    element.append(value);
    element.append(createHtmlElement("dd", "tile-detail", tile.detail));
    container.append(element);
  }
}

// ------------------------------------------------------------------ page sections

const GROUP_SERIES = [
  { key: "living", label: "Wohnräume", colorClass: "color-series-1" },
  { key: "utility", label: "Technikraum und Werkstatt", colorClass: "color-series-2" },
];

// Series the reader has hidden via the legend, per chart. Kept here so a redraw (resize) remembers it.
const hiddenSeries = { overview: new Set(), vacation: new Set(), hourOfDay: new Set() };

function buildGroupSeries(source, hiddenKeys) {
  return GROUP_SERIES
    .filter((group) => !hiddenKeys.has(group.key))
    .map((group) => ({ ...group, values: source[group.key] }));
}

// Returns whether the series is visible after the click. The last visible series stays,
// because an empty chart would look broken.
function toggleSeries(hiddenKeys, key) {
  if (hiddenKeys.has(key)) {
    hiddenKeys.delete(key);
    return true;
  }
  const visibleCount = GROUP_SERIES.length - hiddenKeys.size;
  if (visibleCount === 1) return true;
  hiddenKeys.add(key);
  return false;
}

function setUpSeriesToggle(legendId, hiddenKeys, redraw) {
  drawLegend(legendId, GROUP_SERIES, {
    onToggle: (key) => {
      const isVisible = toggleSeries(hiddenKeys, key);
      redraw();
      return isVisible;
    },
  });
}

function drawHero(data) {
  const firstDay = dayFormat.format(parseDay(data.meta.firstDay));
  const lastDay = dayFormat.format(parseDay(data.meta.lastDay));
  document.getElementById("hero-period").textContent = `Messung ${firstDay} bis ${lastDay}2026`;
  drawTiles("kpi-tiles", [
    { label: "Wohnräume im Alltag", value: numberFormat.format(data.kpis.everydayLivingMean), unit: "Bq/m³", detail: "Mittel ohne Urlaub" },
    {
      label: "Wohnräume im Urlaub", value: numberFormat.format(data.kpis.vacationLivingMean), unit: "Bq/m³",
      detail: `01.–06.08., ${decimalFormat.format(data.kpis.vacationFactor)}-mal so hoch`,
    },
    { label: "Messzeitraum", value: numberFormat.format(data.meta.dayCount), unit: "Tage", detail: `${numberFormat.format(data.meta.rowCount)} Meldungen` },
  ]);
  document.getElementById("data-summary").textContent =
    `${numberFormat.format(data.meta.rowCount)} Gerätemeldungen aus ${data.meta.dayCount} Tagen: Radon in sieben Räumen, `
    + "Raumluft in Küche und Schlafzimmer, dazu Wetterdaten. Radon und Raumluft kommen etwa alle 10 Minuten, das Wetter stündlich.";
}

function drawOverview(data) {
  const xs = data.daily.days.map(parseDay);
  drawLineChart({
    container: document.getElementById("overview-chart"),
    ariaLabel: "Liniendiagramm: Radon-Tagesmittel von März bis Oktober 2026. Pfeiltasten wählen einen Tag.",
    xs,
    series: buildGroupSeries(data.daily, hiddenSeries.overview),
    unit: "Bq/m³",
    formatX: (time) => longDayFormat.format(time),
    xTicks: () => xs.filter((time) => new Date(time).getDate() === 1).map((time) => ({ x: time, label: monthFormat.format(time) })),
    bands: [{ from: parseDay("2026-07-31"), to: parseDay("2026-08-07"), label: "Urlaub" }],
    markers: [{ x: parseDay(data.ventilation.startDay), label: "Lüftung an (vermutet)" }],
    referenceLines: [{ value: data.meta.referenceLevel, label: "Referenzwert 300" }],
  });
}

function buildDayTicks(xs, chartWidth) {
  const dayStep = chartWidth < NARROW_CHART_WIDTH ? 2 : 1;
  const midnights = xs.filter((time) => new Date(time).getHours() === 0);
  return midnights.filter((_, index) => index % dayStep === 0).map((time) => ({ x: time, label: dayFormat.format(time) }));
}

function drawVacation(data) {
  const xs = data.vacation.hours.map((isoHour) => new Date(isoHour).getTime());
  // Times found in the 10-minute CO₂ data: last rise at 05:11, first rise after the return at 20:03.
  const absence = { from: new Date("2026-07-31T06:00:00").getTime(), to: new Date("2026-08-06T20:00:00").getTime(), label: "Haus leer" };
  drawLineChart({
    container: document.getElementById("vacation-radon-chart"),
    ariaLabel: "Liniendiagramm: Radon-Stundenmittel vom 29.07. bis 08.08. Pfeiltasten wählen eine Stunde.",
    xs,
    series: buildGroupSeries(data.vacation, hiddenSeries.vacation),
    unit: "Bq/m³",
    formatX: formatHour,
    xTicks: (chartWidth) => buildDayTicks(xs, chartWidth),
    bands: [absence],
    referenceLines: [{ value: data.meta.referenceLevel, label: "Referenzwert 300" }],
  });
  drawLineChart({
    container: document.getElementById("vacation-co2-chart"),
    ariaLabel: "Liniendiagramm: CO₂ in der Küche vom 29.07. bis 08.08. Pfeiltasten wählen eine Stunde.",
    xs,
    series: [{ label: "CO₂ Küche", colorClass: "color-neutral", values: data.vacation.kitchenCo2 }],
    unit: "ppm",
    formatX: formatHour,
    xTicks: (chartWidth) => buildDayTicks(xs, chartWidth),
    bands: [absence],
  });
}

function drawRanking(data, period) {
  const entries = data.ranking[period];
  const hourCount = data.ranking[`${period}HourCount`];
  const periodLabel = period === "everyday" ? "im Alltag" : "im Urlaub (01.–06.08.)";
  document.getElementById("ranking-title").textContent =
    `Radon ${periodLabel}, Mittel in Bq/m³ (${numberFormat.format(hourCount)} Stunden)`;

  // One scale for both periods, so the bars show how much higher the vacation values are.
  const scaleMax = Math.max(...data.ranking.vacation.map((entry) => entry.mean));
  const chart = document.getElementById("ranking-chart");
  const tableBody = document.querySelector("#ranking-table tbody");
  const isFirstDraw = chart.children.length === 0;
  if (isFirstDraw) {
    for (let index = 0; index < entries.length; index += 1) {
      const row = createHtmlElement("div", "bar-row");
      row.tabIndex = 0;
      const track = createHtmlElement("div", "bar-track");
      track.append(createHtmlElement("div", "bar-fill"), createHtmlElement("span", "bar-value"));
      row.append(createHtmlElement("span", "bar-label"), track);
      chart.append(row);
    }
  }
  tableBody.replaceChildren();

  entries.forEach((entry, index) => {
    const row = chart.children[index];
    row.querySelector(".bar-label").textContent = entry.room;
    row.querySelector(".bar-fill").style.width = `${(entry.mean / scaleMax) * BAR_MAX_WIDTH_PERCENT}%`;
    row.querySelector(".bar-value").textContent = numberFormat.format(entry.mean);
    const details = [
      { value: numberFormat.format(entry.median), label: "Median" },
      { value: numberFormat.format(entry.max), label: "höchstes Stundenmittel" },
      { value: `${decimalFormat.format(entry.shareOverHigh)} %`, label: "der Stunden über 100" },
      { value: numberFormat.format(entry.hoursOverReference), label: "Stunden über 300" },
    ];
    row.onpointermove = (event) => showTooltip(entry.room, details, event.clientX, event.clientY);
    row.onpointerleave = hideTooltip;
    row.onfocus = () => {
      const bounds = row.getBoundingClientRect();
      showTooltip(entry.room, details, bounds.left + bounds.width / 2, bounds.top);
    };
    row.onblur = hideTooltip;

    const hoursOverHigh = Math.round((entry.shareOverHigh / 100) * hourCount);
    const tableRow = createHtmlElement("tr");
    tableRow.append(createHtmlElement("td", "", entry.room));
    for (const value of [entry.mean, entry.median, entry.max, hoursOverHigh, entry.hoursOverReference]) {
      tableRow.append(createHtmlElement("td", "num", numberFormat.format(value)));
    }
    tableBody.append(tableRow);
  });
}

function setUpRankingToggle(data) {
  const buttons = document.querySelectorAll(".segmented button");
  buttons.forEach((button) => {
    button.addEventListener("click", () => {
      buttons.forEach((other) => other.setAttribute("aria-pressed", String(other === button)));
      drawRanking(data, button.dataset.period);
    });
  });
}

// Explanations are an interpretation of the data, not a measurement (see note under the table).
const ROOM_REASONS = {
  "Werkstatt": "hängt am Boden, wohl außerhalb der Lüftung",
  "Technikraum": "hängt am Boden, wohl außerhalb der Lüftung",
  "Küche-Sockel": "misst in Bodennähe, nah am Eintritt",
  "Schlafzimmer": "nachts geschlossen; anderer Sensortyp",
  "Wohnzimmer": "nachts zu, tagsüber gelüftet",
  "Küche": "nachts zu, tagsüber gelüftet",
  "Büro": "nachts zu, tagsüber gelüftet",
};
// Below this ratio between highest and lowest hour the room has no real daily pattern.
const FLAT_DAY_RATIO = 1.5;
const longMonthFormat = new Intl.DateTimeFormat("de-AT", { month: "long" });

function drawRoomProfiles(data) {
  const tableBody = document.querySelector("#room-profile-table tbody");
  tableBody.replaceChildren();
  for (const profile of data.roomProfiles) {
    const isFlat = profile.peakHourMean / profile.lowHourMean < FLAT_DAY_RATIO;
    const dayText = isFlat
      ? `kaum Tagesgang (${profile.lowHourMean} bis ${profile.peakHourMean})`
      : `${profile.peakHour} Uhr: ${profile.peakHourMean}, ${profile.lowHour} Uhr: ${profile.lowHourMean}`;
    const monthName = longMonthFormat.format(new Date(2026, profile.peakMonth - 1, 1));
    const row = createHtmlElement("tr");
    row.append(createHtmlElement("td", "", profile.room));
    row.append(createHtmlElement("td", "", dayText));
    row.append(createHtmlElement("td", "", `${monthName}: ${profile.peakMonthMean}`));
    row.append(createHtmlElement("td", "num", numberFormat.format(profile.hoursOverHigh)));
    row.append(createHtmlElement("td", "", ROOM_REASONS[profile.room]));
    tableBody.append(row);
  }
}

function drawVentilation(data) {
  const days = data.ventilation.days.map(parseDay);
  const startIndex = data.ventilation.days.indexOf(data.ventilation.startDay);
  drawTiles("ventilation-tiles", [
    { label: "Küche vor dem 31.03.", value: numberFormat.format(data.kpis.kitchenBeforeVentilation), unit: "Bq/m³", detail: "Mittel 24.–30.03." },
    { label: "Küche danach", value: numberFormat.format(data.kpis.kitchenAfterVentilation), unit: "Bq/m³", detail: "Mittel 31.03.–30.04." },
  ]);
  drawLegend("ventilation-legend", [
    { label: "vor dem 31.03.", colorClass: "color-neutral" },
    { label: "ab dem 31.03.", colorClass: "color-series-1" },
  ], { isBox: true });
  drawColumnChart({
    container: document.getElementById("ventilation-chart"),
    ariaLabel: "Säulendiagramm: Radon-Tagesmittel in der Küche vom 24.03. bis 20.04. Pfeiltasten wählen einen Tag.",
    values: data.ventilation.kitchen,
    unit: "Bq/m³",
    label: "Küche",
    colorClassOf: (index) => (index < startIndex ? "color-neutral" : "color-series-1"),
    formatX: (index) => longDayFormat.format(days[index]),
    xTicks: (chartWidth) => {
      const dayStep = chartWidth < NARROW_CHART_WIDTH ? 7 : 3;
      return days.map((time, index) => ({ x: index, label: dayFormat.format(time) })).filter((_, index) => index % dayStep === 0);
    },
    // The marker sits between the last column before and the first column after the start.
    markers: [{ x: startIndex - 0.5, label: "Lüftung an (vermutet)" }],
  });
}

function drawHourOfDay(data) {
  const hours = data.hourOfDay.living.map((_, hour) => hour);
  drawLineChart({
    container: document.getElementById("hour-chart"),
    ariaLabel: "Liniendiagramm: mittleres Radon je Uhrzeit. Pfeiltasten wählen eine Stunde.",
    xs: hours,
    series: buildGroupSeries(data.hourOfDay, hiddenSeries.hourOfDay),
    unit: "Bq/m³",
    formatX: (hour) => `${hour} Uhr`,
    xTicks: () => hours.filter((hour) => hour % 3 === 0).map((hour) => ({ x: hour, label: `${hour} Uhr` })),
  });
}

// Reference levels for homes in Bq/m³ (annual mean). Sources are linked in the page section.
const HIGHLIGHTED_COUNTRY = "Österreich";
const REFERENCE_LEVELS = [
  { country: "WHO-Empfehlung", value: 100, detail: "falls nicht erreichbar: höchstens 300" },
  { country: "USA", value: 148, detail: "Aktionswert der Umweltbehörde EPA (4 pCi/L)" },
  { country: "Kanada", value: 200, detail: "seit 2007, davor 800" },
  { country: "Großbritannien", value: 200, detail: "Zielwert nach einer Sanierung: 100" },
  { country: "Schweden", value: 200, detail: "seit 2004, davor 400" },
  { country: "Deutschland", value: 300, detail: "Strahlenschutzgesetz" },
  { country: "Schweiz", value: 300, detail: "seit 2018, davor 1 000" },
  { country: "Österreich", value: 300, detail: "Radonschutzverordnung 2020" },
];
const BAR_MAX_WIDTH_PERCENT = 80;

function drawReferenceLevels() {
  const chart = document.getElementById("levels-chart");
  const scaleMax = Math.max(...REFERENCE_LEVELS.map((level) => level.value));
  chart.replaceChildren();
  for (const level of REFERENCE_LEVELS) {
    const isHighlighted = level.country === HIGHLIGHTED_COUNTRY;
    const fill = createHtmlElement("div", isHighlighted ? "bar-fill" : "bar-fill is-muted");
    fill.style.width = `${(level.value / scaleMax) * BAR_MAX_WIDTH_PERCENT}%`;
    const track = createHtmlElement("div", "bar-track");
    track.append(fill, createHtmlElement("span", "bar-value", numberFormat.format(level.value)));
    track.append(createHtmlElement("span", "bar-detail", level.detail));
    const row = createHtmlElement("div", "bar-row");
    row.append(createHtmlElement("span", "bar-label", level.country), track);
    chart.append(row);
  }
}

// ------------------------------------------------------------------ start

function drawCharts(data) {
  drawOverview(data);
  drawVacation(data);
  drawVentilation(data);
  drawHourOfDay(data);
}

function start() {
  const data = window.RADON_DATA;
  if (!data) {
    document.querySelector("main").hidden = true;
    document.getElementById("load-error").hidden = false;
    return;
  }
  drawHero(data);
  drawRanking(data, "everyday");
  setUpRankingToggle(data);
  drawRoomProfiles(data);
  drawReferenceLevels();
  setUpSeriesToggle("overview-legend", hiddenSeries.overview, () => drawOverview(data));
  setUpSeriesToggle("vacation-legend", hiddenSeries.vacation, () => drawVacation(data));
  setUpSeriesToggle("hour-legend", hiddenSeries.hourOfDay, () => drawHourOfDay(data));
  drawCharts(data);

  // SVG charts are drawn in pixels, so they have to be redrawn when the width changes.
  let resizeTimer = 0;
  window.addEventListener("resize", () => {
    window.clearTimeout(resizeTimer);
    resizeTimer = window.setTimeout(() => drawCharts(data), 150);
  });
}

start();
